glsl1.vert:
precision mediump float;
uniform highp mat4 cc_matViewProj;
attribute highp vec3 a_position;
attribute vec4 a_color;
varying vec4 v_color;
vec4 vert () {
  vec4 pos = cc_matViewProj * vec4(a_position, 1);
  pos.z -= 0.000001;
  v_color = a_color;
  return pos;
}
void main() { gl_Position = vert(); }

